# Office productivity tools
def res(rows_id='r'):return f"<div class='res' aria-live='polite'><h2>Result</h2><table id='{rows_id}'></table></div>"
def num(i,l,v,extra=''):return f"<label for='{i}'>{l}</label><input id='{i}' type='number' step='any' inputmode='decimal' value='{v}' {extra}>"
LIVE="document.querySelectorAll('.calc input,.calc select,.calc textarea').forEach(function(e){e.addEventListener('input',run);e.addEventListener('change',run)});run();"
ROWS="function show(rows){UI.$('#r').innerHTML=rows.map(function(x){return '<tr><td>'+x[0]+'</td><td><b>'+x[1]+'</b></td></tr>'}).join('')}"
# word counter
ui="<div class='calc wide'><label for='t'>Paste or type your text</label><textarea id='t' rows='12' placeholder='Start typing…'></textarea></div><div class='stats' id='st'></div><p class='priv'>🔒 Your text stays in your browser—nothing is sent to a server.</p>"
js="""function run(){var c=DK.countText(UI.$('#t').value),m=function(x){return !c.words?'0 sec':x<1?Math.ceil(x*60)+' sec':Math.round(x)+' min'};
UI.$('#st').innerHTML=[['Words',DK.fmt(c.words)],['Characters',DK.fmt(c.chars)],['Characters (no spaces)',DK.fmt(c.charsNoSpaces)],['Sentences',DK.fmt(c.sentences)],['Paragraphs',DK.fmt(c.paragraphs)],['Reading time',m(c.readMin)],['Speaking time',m(c.speakMin)]].map(function(x){return '<div><b>'+x[1]+'</b><span>'+x[0]+'</span></div>'}).join('')}
UI.$('#t').addEventListener('input',run);run();"""
O={}
def add(slug,cat,h,t,d,ui,js,g,libs=()):O[slug]=dict(cat=cat,h=h,t=t,d=d,ui=ui,js=js,g=g,libs=libs)
FAQ=lambda *qa:"<h2>FAQ</h2>"+"".join(f"<h3>{q}</h3><p>{a}</p>" for q,a in qa)
add("word-counter","Text tools","Word Counter","Word Counter – Count Words, Characters & Reading Time","Free word counter: count words, characters with and without spaces, sentences, paragraphs, and reading and speaking time as you type.",ui,js,
"<h2>How words are counted</h2><p>A word is any run of letters or numbers, including contractions (<i>don't</i>), hyphenated words (<i>well-known</i>) and email addresses. Punctuation and emoji alone don't count. This matches how Microsoft Word and Google Docs count in normal prose.</p><h2>Reading and speaking time</h2><p>Reading time uses 238 words per minute, the average silent reading speed for English non-fiction found in a 2019 meta-analysis of 190 studies (Brysbaert). Speaking time uses 140 words per minute, a typical pace for presentations.</p><h2>Common limits</h2><ul><li>LinkedIn post: 3,000 characters</li><li>X (Twitter) post: 280 characters</li><li>Meta description: about 155 characters</li><li>College application essay (Common App): 650 words</li></ul>"+FAQ(("Is my text saved or uploaded?","No. Counting happens in your browser; refresh the page and it's gone."),("Do spaces count as characters?","Yes in “Characters”; “Characters (no spaces)” excludes spaces, tabs and line breaks.")))
ui="<div class='calc wide'><label for='t'>Your text</label><textarea id='t' rows='8'>the quick brown fox jumps over the lazy dog</textarea><div class='btnrow'>"+"".join(f"<button type='button' class='btn sm' data-m='{m}'>{l}</button>" for m,l in [("sentence","Sentence case"),("lower","lower case"),("upper","UPPER CASE"),("title","Title Case"),("capitalized","Capitalized Case"),("camel","camelCase"),("pascal","PascalCase"),("snake","snake_case"),("kebab","kebab-case"),("constant","CONSTANT_CASE"),("alternating","aLtErNaTiNg"),("inverse","InVeRsE")])+"</div><label for='o'>Result</label><textarea id='o' rows='8' readonly></textarea><button type='button' class='btn' id='cp'>Copy result</button></div>"
js="""document.querySelectorAll('[data-m]').forEach(function(b){b.onclick=function(){UI.$('#o').value=DK.convertCase(UI.$('#t').value,b.dataset.m)}});UI.$('#cp').onclick=function(){UI.copy(UI.$('#o').value,this)};"""
add("case-converter","Text tools","Case Converter","Case Converter – UPPER, lower, Title Case, camelCase & More","Convert text to sentence case, lower case, UPPER CASE, Title Case, camelCase, snake_case, kebab-case and more. Instant and private.",ui,js,
"<h2>Which case should I use?</h2><ul><li><b>Sentence case</b> – emails, body text and most UI labels. First letter of each sentence capitalized.</li><li><b>Title Case</b> – headlines and document titles. Major words capitalized; articles, conjunctions and prepositions of three letters or fewer (<i>a, and, of, the, to, for</i>) stay lowercase unless they come first or last, following AP style.</li><li><b>Capitalized Case</b> – every word starts with a capital.</li><li><b>camelCase / PascalCase</b> – variable and class names in code.</li><li><b>snake_case / CONSTANT_CASE</b> – Python variables, database columns, environment variables.</li><li><b>kebab-case</b> – URLs and CSS class names.</li></ul><h2>Fix accidental CAPS LOCK</h2><p>Paste the text and choose <b>Sentence case</b>. Proper nouns will be lowercased, so give names a quick check afterwards.</p>"+FAQ(("Does it change my original text?","No, the result appears in a separate box for you to copy."),))
ui="<div class='calc wide two'><div><label for='a'>Original text</label><textarea id='a' rows='12'>Hello team,\nThe meeting is on Monday.\nPlease bring the report.</textarea></div><div><label for='b'>Changed text</label><textarea id='b' rows='12'>Hello team,\nThe meeting is on Tuesday.\nPlease bring the report.\nThanks!</textarea></div></div><div class='btnrow'><label class='chk'><input id='ws' type='checkbox'> Ignore whitespace</label><label class='chk'><input id='ic' type='checkbox'> Ignore case</label></div><p id='sum' class='status'></p><div id='diff' class='diff'></div><p class='priv'>🔒 Comparison runs in your browser; your text is never uploaded.</p>"
js="""function run(){try{var d=DK.diffLines(UI.$('#a').value,UI.$('#b').value,{ignoreWs:UI.$('#ws').checked,ignoreCase:UI.$('#ic').checked}),ad=0,rm=0;
UI.$('#diff').innerHTML=d.map(function(x){if(x.t==='+')ad++;if(x.t==='-')rm++;return '<div class="dl '+(x.t==='+'?'add':x.t==='-'?'del':'')+'"><span class="ln">'+(x.a||'')+'</span><span class="ln">'+(x.b||'')+'</span><span class="sg">'+(x.t==='='?' ':x.t)+'</span><code>'+DK.esc(x.s)+'</code></div>'}).join('');
UI.$('#sum').textContent=ad||rm?(rm+' line(s) removed, '+ad+' line(s) added.'):'No differences found.'}catch(e){UI.$('#sum').textContent=e.message}}
['#a','#b'].forEach(function(s){UI.$(s).addEventListener('input',run)});['#ws','#ic'].forEach(function(s){UI.$(s).addEventListener('change',run)});run();"""
add("text-compare","Text tools","Text Compare (Diff Checker)","Text Compare – Find the Difference Between Two Texts","Compare two texts line by line and highlight added and removed lines. Free diff checker for contracts, drafts, code and config files. Private.",ui,js,
"<h2>How to compare two documents</h2><p>Paste the original on the left and the revised version on the right. Removed lines are shown in red with a minus, added lines in green with a plus, and unchanged lines in between, with line numbers from both versions. A changed line appears as one removed and one added line.</p><h2>Uses at work</h2><ul><li>Check what a counterparty changed in a contract clause.</li><li>Compare two exports of a list to find new or missing entries.</li><li>Review edits to policy text, scripts or config files.</li></ul><p>Tip: if the texts were re-wrapped, enable <b>Ignore whitespace</b>.</p>"+FAQ(("Is my text uploaded?","No. The comparison (a longest-common-subsequence algorithm) runs in your browser."),("Can I compare Word files?","Copy the text out of each document and paste it here.")))
# business days
ui="<form class='calc' onsubmit='return false'><label for='s'>Start date</label><input id='s' type='date' value='2026-11-02'><label for='e'>End date</label><input id='e' type='date' value='2026-11-30'><label class='chk'><input id='h' type='checkbox' checked> Exclude US federal holidays</label><label for='x'>Other days off (optional, YYYY-MM-DD, comma separated)</label><input id='x' type='text' placeholder='2026-11-27'><hr><label for='n'>Or add business days to the start date</label><input id='n' type='number' value='10'></form>"+res()
js=ROWS+"""function run(){var o={holidays:UI.$('#h').checked,extra:UI.$('#x').value.split(/[,\\s]+/).filter(Boolean)},r=DK.businessDays(UI.$('#s').value,UI.$('#e').value,o),n=+UI.$('#n').value,a=DK.addBusinessDays(UI.$('#s').value,n,o);
if(!r)return show([['Enter valid dates','—']]);show([['Business days (start & end included)',r.businessDays],['Calendar days',r.totalDays],['Weekend days',r.weekendDays],['Holidays / days off on weekdays',r.holidays.length?r.holidays.map(function(h){return h.date+' '+h.name}).join('<br>'):'none'],[n+' business days after start',a?new Date(a+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',year:'numeric',month:'short',day:'numeric'}):'—']])}"""+LIVE
add("business-days-calculator","Date & time","Business Days Calculator","Business Days Calculator – Working Days Between Dates (US Holidays)","Count working days between two dates excluding weekends and US federal holidays, or add business days to a date. Like Excel NETWORKDAYS.",ui,js,
"<h2>How business days are counted</h2><p>The count includes both the start and end date, the same as Excel's <code>NETWORKDAYS</code> function. Saturdays and Sundays are excluded, and, if ticked, the 11 US federal holidays.</p><h2>US federal holidays used</h2><p>New Year's Day, Martin Luther King Jr. Day (3rd Monday of January), Presidents' Day (3rd Monday of February), Memorial Day (last Monday of May), Juneteenth (June 19), Independence Day (July 4), Labor Day (1st Monday of September), Columbus Day (2nd Monday of October), Veterans Day (November 11), Thanksgiving (4th Thursday of November) and Christmas Day. A holiday on Saturday is observed the Friday before, and one on Sunday the Monday after—following OPM rules. For example, in 2026 Independence Day falls on Saturday, so Friday, July 3 is the day off.</p><h2>Adding business days</h2><p>“10 business days after” counts forward from the start date, skipping weekends and holidays—useful for payment terms, notice periods and SLA deadlines.</p>"+FAQ(("How many working days are in 2026?","There are 261 weekdays in 2026; minus 11 federal holidays leaves 250 working days."),("Does it include state holidays?","No—add them (or company days off) in the “Other days off” box.")))
# time card
days=["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];dv=[("9:00 AM","5:30 PM",30)]*5+[("","",0)]*2
ui="<form class='calc wide' onsubmit='return false'><table class='tc'><tr><th>Day</th><th>Start</th><th>End</th><th>Break (min)</th><th>Hours</th></tr>"+"".join(f"<tr><td>{d}</td><td><input id='i{k}' type='text' value='{v[0]}' placeholder='9:00 AM'></td><td><input id='o{k}' type='text' value='{v[1]}' placeholder='5:00 PM'></td><td><input id='b{k}' type='number' min='0' value='{v[2]}'></td><td id='hh{k}'></td></tr>" for k,(d,v) in enumerate(zip(days,dv)))+"</table><div class='row3'>"+num("rate","Hourly rate ($)",20)+num("ot","Overtime after (hours/week)",40)+num("om","Overtime multiplier",1.5)+"</div></form>"+res()
js=ROWS+"""function run(){var rows=[];for(var k=0;k<7;k++)rows.push({in:UI.$('#i'+k).value,out:UI.$('#o'+k).value,brk:UI.$('#b'+k).value});var r=DK.timecard(rows,+UI.$('#rate').value,+UI.$('#ot').value,+UI.$('#om').value);
r.days.forEach(function(h,k){UI.$('#hh'+k).textContent=!(rows[k].in||rows[k].out)?'':h==null?'check time':DK.hm(h)});show([['Total hours',DK.hm(r.hours)+' ('+DK.fmt(r.hours)+' h)'],['Regular hours',DK.fmt(r.regular)],['Overtime hours',DK.fmt(r.overtime)],['Gross pay',DK.money(r.pay)]])}"""+LIVE.replace("'.calc input","'.calc input")
add("time-card-calculator","Date & time","Time Card Calculator","Time Card Calculator – Weekly Hours, Breaks & Overtime Pay","Free weekly timesheet calculator: enter start and end times and breaks to get total hours, overtime after 40 hours, and gross pay. Handles overnight shifts.",ui,js,
"<h2>How to use the time card calculator</h2><p>Enter start and end times in any common format—<code>9:00 AM</code>, <code>9am</code>, <code>17:30</code> or <code>1730</code>. Add unpaid break minutes for each day. If the end time is earlier than the start, the shift is treated as overnight (for example 10:00 PM to 6:00 AM = 8 hours).</p><h2>Decimal hours vs. hours and minutes</h2><p>Payroll systems usually want decimal hours: 7 h 30 min = 7.5 hours, 7 h 45 min = 7.75 hours. Both formats are shown.</p><h2>Overtime</h2><p>Under the federal Fair Labor Standards Act, non-exempt employees must be paid at least 1.5 × their regular rate for hours worked over 40 in a workweek. Some states, such as California, also require daily overtime after 8 hours—adjust as needed for your situation.</p>"+FAQ(("Is 30 minutes for lunch deducted automatically?","No, only the break minutes you enter are deducted."),("Is this payroll or legal advice?","No. It's an arithmetic aid; check your employer's policy and state law.")))
# salary
ui="<form class='calc' onsubmit='return false'>"+num("a","Pay amount ($)",25)+"<label for='p'>Per</label><select id='p'><option value='hour'>Hour</option><option value='day'>Day</option><option value='week'>Week</option><option value='biweek'>Every 2 weeks</option><option value='semimonth'>Twice a month</option><option value='month'>Month</option><option value='year'>Year</option></select>"+num("hw","Hours per week",40)+num("wy","Paid weeks per year",52)+"</form>"+res()
js=ROWS+"""function run(){var r=DK.salary(+UI.$('#a').value,UI.$('#p').value,+UI.$('#hw').value,+UI.$('#wy').value);show([['Hourly',DK.money(r.hourly)],['Daily (5-day week)',DK.money(r.daily)],['Weekly',DK.money(r.weekly)],['Biweekly (26 checks)',DK.money(r.biweekly)],['Semi-monthly (24 checks)',DK.money(r.semimonthly)],['Monthly',DK.money(r.monthly)],['Annual',DK.money(r.annual)]])}"""+LIVE
add("hourly-to-salary-calculator","Pay & money","Hourly to Salary Calculator","Hourly to Salary Calculator – Convert Hourly, Weekly, Monthly & Annual Pay","Convert hourly wage to annual salary and back, plus weekly, biweekly, semi-monthly and monthly pay. Adjustable hours per week and paid weeks.",ui,js,
"<h2>The formula</h2><p>Annual salary = hourly rate × hours per week × paid weeks per year. At 40 hours and 52 weeks, that's 2,080 hours a year, so <b>$25/hour ≈ $52,000/year</b>. A quick mental shortcut: double the hourly rate and add three zeros.</p><h2>Annual to hourly</h2><p>Divide salary by 2,080: $75,000 ÷ 2,080 = $36.06 per hour.</p><h2>Biweekly vs. semi-monthly</h2><p>Biweekly pay comes every two weeks (26 paychecks a year); semi-monthly comes twice a month (24 paychecks), so each semi-monthly check is slightly larger.</p><p>All figures are gross pay, before taxes and deductions.</p>"+FAQ(("What if I have unpaid time off?","Lower “Paid weeks per year”—for example 50 for two unpaid weeks."),))
# percentage
ui="<form class='calc' onsubmit='return false'><div class='pc'>What is "+"<input id='p1' type='number' step='any' value='15'>% of <input id='x1' type='number' step='any' value='200'>? <b id='r1'></b></div><div class='pc'><input id='x2' type='number' step='any' value='30'> is what % of <input id='y2' type='number' step='any' value='120'>? <b id='r2'></b></div><div class='pc'>% change from <input id='a3' type='number' step='any' value='80'> to <input id='b3' type='number' step='any' value='100'>? <b id='r3'></b></div><div class='pc'>Increase <input id='x4' type='number' step='any' value='50'> by <input id='p4' type='number' step='any' value='10'>% <b id='r4'></b></div><div class='pc'>Decrease <input id='x5' type='number' step='any' value='50'> by <input id='p5' type='number' step='any' value='10'>% <b id='r5'></b></div><div class='pc'>% difference between <input id='a6' type='number' step='any' value='40'> and <input id='b6' type='number' step='any' value='60'> <b id='r6'></b></div></form>"
js="""function v(i){return parseFloat(UI.$('#'+i).value)}function o(i,x,s){UI.$('#'+i).textContent='= '+(isFinite(x)?DK.fmt(x,4)+(s||''):'—')}
function run(){o('r1',DK.pct.of(v('p1'),v('x1')));o('r2',DK.pct.what(v('x2'),v('y2')),'%');var c=DK.pct.change(v('a3'),v('b3'));UI.$('#r3').textContent='= '+(isFinite(c)?(c>0?'+':'')+DK.fmt(c,4)+'% ('+(c>=0?'increase':'decrease')+')':'—');o('r4',DK.pct.inc(v('x4'),v('p4')));o('r5',DK.pct.dec(v('x5'),v('p5')));o('r6',DK.pct.diff(v('a6'),v('b6')),'%')}"""+LIVE
add("percentage-calculator","Pay & money","Percentage Calculator","Percentage Calculator – % Of, % Change, Increase & Decrease","Six percentage calculators in one: X% of Y, X is what percent of Y, percent change, increase or decrease by a percent, and percent difference.",ui,js,
"<h2>Percentage formulas</h2><ul><li><b>X% of Y</b> = X ÷ 100 × Y. 15% of 200 = 30.</li><li><b>X is what % of Y</b> = X ÷ Y × 100. 30 is 25% of 120.</li><li><b>Percent change</b> = (new − old) ÷ |old| × 100. From 80 to 100 is +25%.</li><li><b>Increase by %</b> = X × (1 + P/100). <b>Decrease by %</b> = X × (1 − P/100).</li><li><b>Percent difference</b> = |A − B| ÷ ((A + B) ÷ 2) × 100, used when neither value is the “original”.</li></ul><h2>A common trap</h2><p>A 20% drop followed by a 20% rise doesn't get you back where you started: 100 → 80 → 96. Percent changes compound; they don't add.</p><h2>Percentage points vs. percent</h2><p>If a conversion rate moves from 4% to 5%, that's a rise of 1 percentage point but a 25% increase.</p>")
