Z=["America/New_York","America/Chicago","America/Denver","America/Phoenix","America/Los_Angeles","America/Anchorage","Pacific/Honolulu","America/Toronto","America/Mexico_City","America/Sao_Paulo","Europe/London","Europe/Dublin","Europe/Paris","Europe/Berlin","Europe/Madrid","Europe/Amsterdam","Europe/Warsaw","Europe/Istanbul","Africa/Lagos","Africa/Johannesburg","Asia/Dubai","Asia/Kolkata","Asia/Singapore","Asia/Manila","Asia/Ho_Chi_Minh","Asia/Bangkok","Asia/Shanghai","Asia/Hong_Kong","Asia/Tokyo","Asia/Seoul","Australia/Sydney","Australia/Perth","Pacific/Auckland","UTC"]
opts="".join(f"<option value='{z}'>{z.replace('_',' ')}</option>" for z in Z)
ui=f"<form class='calc wide' onsubmit='return false'><div class='row3'><div><label for='d'>Date</label><input id='d' type='date' value='2026-11-10'></div><div><label for='tm'>Time</label><input id='tm' type='time' value='09:00'></div><div><label for='z0'>In time zone</label><select id='z0'>{opts}</select></div></div><label>Other participants' time zones</label><div class='row3'>"+"".join(f"<select id='z{i}'>{opts}</select>" for i in (1,2,3,4,5))+"</div></form><div id='tz' class='tzout'></div><p class='muted'>Green = 9 AM–5 PM working hours, yellow = 7–9 AM or 5–9 PM, gray = night. Daylight saving time is applied automatically for the chosen date.</p>"
js="""var def=['America/New_York','America/Los_Angeles','Europe/London','Asia/Kolkata','Asia/Tokyo','Australia/Sydney'];try{var mine=Intl.DateTimeFormat().resolvedOptions().timeZone}catch(e){}
for(var i=0;i<6;i++){var s=UI.$('#z'+i);if(i===0&&mine&&!s.querySelector('option[value="'+mine+'"]')){var op=document.createElement('option');op.value=mine;op.textContent=mine.replace(/_/g,' ');s.prepend(op)}s.value=i===0&&mine?mine:def[i]}
function cls(h){return h>=9&&h<17?'work':(h>=7&&h<9)||(h>=17&&h<21)?'edge':'night'}
function run(){var z=[0,1,2,3,4,5].map(function(i){return UI.$('#z'+i).value}),u=DK.zonedToUtc(UI.$('#d').value,UI.$('#tm').value,z[0]);if(u==null){UI.$('#tz').innerHTML='';return}
var base=u-(DK.hourIn(u,z[0])%1)*36e5,h='<table class="tzg"><tr><th>Time zone</th><th>Meeting time</th>'+Array.from({length:24},function(_,k){return '<th>'+(k?'+'+k:'')+'</th>'}).join('')+'</tr>';
z.forEach(function(t){h+='<tr><td>'+DK.esc(t.replace(/_/g,' '))+'</td><td><b>'+DK.fmtZone(u,t)+'</b></td>';for(var k=0;k<24;k++){var ms=base+(k-Math.floor(DK.hourIn(u,z[0])))*36e5+Math.floor(DK.hourIn(u,z[0]))*36e5,hr=Math.floor(DK.hourIn(base+k*36e5,t));h+='<td class="'+cls(hr)+'">'+(hr%12||12)+(hr<12?'a':'p')+'</td>'}h+='</tr>'});UI.$('#tz').innerHTML=h+'</table>'}"""+LIVE
add("time-zone-meeting-planner","Date & time","Time Zone Meeting Planner","Time Zone Meeting Planner – Find a Time That Works Across Zones","Plan meetings across time zones: see a meeting time in up to 6 cities with working hours highlighted. Handles daylight saving time automatically.",ui,js,
"<h2>Find a meeting time for a distributed team</h2><p>Set the date, time and your time zone, then pick your colleagues' zones. You'll see the meeting time for everyone, plus a 24-hour strip starting at your chosen hour so you can spot the slot where most people are in working hours (green).</p><h2>Daylight saving time</h2><p>The US changes clocks on the second Sunday of March and the first Sunday of November; Europe changes on the last Sundays of March and October. For a few weeks each year the gap between New York and London is 4 hours instead of 5. The planner uses your browser's time zone database, so it always applies the rules for the date you pick.</p><h2>Tips for global meetings</h2><ul><li>US East Coast + Europe: 8–11 AM New York time.</li><li>US + India: early morning US or late evening India—rotate who takes the inconvenient slot.</li><li>US West Coast + Asia-Pacific: late afternoon Pacific time.</li></ul>"+FAQ(("Which zone is ‘Ho Chi Minh’ or ‘Kolkata’?","They are IANA names for Vietnam (UTC+7) and India (UTC+5:30)."),))
# meeting cost
ui="<form class='calc' onsubmit='return false'>"+num("n","Number of attendees",6)+num("r","Average pay",85000)+"<label for='t'>Pay is</label><select id='t'><option value='y'>Annual salary ($/year)</option><option value='h'>Hourly rate ($/hour)</option></select>"+num("m","Meeting length (minutes)",60)+num("w","Times per week (recurring)",1)+num("k","Overhead multiplier (benefits, taxes; 1 = salary only)",1.3)+"</form>"+res()
js=ROWS+"""function run(){var k=+UI.$('#k').value||1,r=DK.meetingCost(+UI.$('#n').value,+UI.$('#r').value*k,UI.$('#t').value==='y',+UI.$('#m').value,+UI.$('#w').value);show([['Cost of this meeting',DK.money(r.perMeeting)],['Cost per minute',DK.money(r.perMinute)],['Loaded hourly cost per person',DK.money(r.hourlyEach)],['Yearly cost if recurring',DK.money(r.perYear)]])}"""+LIVE
add("meeting-cost-calculator","Pay & money","Meeting Cost Calculator","Meeting Cost Calculator – What Does This Meeting Really Cost?","Calculate the cost of a meeting from attendees, salaries and length—per meeting and per year for recurring meetings. Include benefits overhead.",ui,js,
"<h2>How meeting cost is calculated</h2><p>Cost = attendees × hourly cost per person × hours. Annual salaries are converted to hourly by dividing by 2,080 (40 hours × 52 weeks). Employers also pay benefits and payroll taxes, which the US Bureau of Labor Statistics puts at roughly 30% on top of wages—hence the default 1.3 overhead multiplier.</p><p><b>Example:</b> 6 people earning $85,000 in a 1-hour meeting: 85,000 × 1.3 ÷ 2,080 = $53.13 per person-hour → $318.75. Weekly, that's about $16,575 a year.</p><h2>Ways to cut meeting cost</h2><ul><li>Default to 25 or 50 minutes instead of 30 or 60.</li><li>Invite only decision makers; send notes to everyone else.</li><li>Replace status meetings with a written update.</li><li>Review recurring meetings every quarter.</li></ul>")
# qr
ui="<form class='calc' onsubmit='return false'><label for='ty'>Type</label><select id='ty'><option value='url'>Website URL</option><option value='text'>Plain text</option><option value='wifi'>Wi-Fi network</option><option value='email'>Email</option><option value='tel'>Phone number</option></select><div id='f-url'><label for='u'>URL</label><input id='u' type='text' value='https://example.com'></div><div id='f-text' hidden><label for='tx'>Text</label><textarea id='tx' rows='3'></textarea></div><div id='f-wifi' hidden><label for='ss'>Network name (SSID)</label><input id='ss' type='text'><label for='pw'>Password</label><input id='pw' type='text'><label for='sec'>Security</label><select id='sec'><option>WPA</option><option>WEP</option><option value='nopass'>None</option></select></div><div id='f-email' hidden><label for='em'>Email address</label><input id='em' type='email'><label for='sj'>Subject</label><input id='sj' type='text'></div><div id='f-tel' hidden><label for='ph'>Phone</label><input id='ph' type='tel'></div><label for='ec'>Error correction</label><select id='ec'><option value='L'>Low (7%)</option><option value='M' selected>Medium (15%)</option><option value='Q'>Quartile (25%)</option><option value='H'>High (30%)</option></select><label for='fg'>Color</label><input id='fg' type='color' value='#000000'></form><div class='res light'><div id='qr'></div><div class='btnrow'><button type='button' class='btn sm' id='png'>Download PNG</button><button type='button' class='btn sm' id='svg'>Download SVG</button></div><p class='muted' id='qinfo'></p></div>"
js="""function payload(){var t=UI.$('#ty').value,e=function(s){return s.replace(/([\\\\;,:"])/g,'\\\\$1')};if(t==='url')return UI.$('#u').value.trim();if(t==='text')return UI.$('#tx').value;
if(t==='wifi'){var sec=UI.$('#sec').value;return 'WIFI:T:'+sec+';S:'+e(UI.$('#ss').value)+';'+(sec==='nopass'?'':'P:'+e(UI.$('#pw').value)+';')+';'}if(t==='email'){var s=UI.$('#sj').value;return 'mailto:'+UI.$('#em').value.trim()+(s?'?subject='+encodeURIComponent(s):'')}return 'tel:'+UI.$('#ph').value.replace(/[^\\d+]/g,'')}
var q=null;function run(){['url','text','wifi','email','tel'].forEach(function(k){UI.$('#f-'+k).hidden=UI.$('#ty').value!==k});var p=payload();if(!p){UI.$('#qr').innerHTML='';q=null;return}
try{q=qrcode(0,UI.$('#ec').value);q.addData(unescape(encodeURIComponent(p)),'Byte');q.make();UI.$('#qr').innerHTML=svg(8);UI.$('#qinfo').textContent=q.getModuleCount()+'×'+q.getModuleCount()+' modules · '+p.length+' characters'}catch(e){UI.$('#qr').textContent='Too much data for a QR code.';q=null}}
function svg(s){var n=q.getModuleCount(),m=4,d='';for(var r=0;r<n;r++)for(var c=0;c<n;c++)if(q.isDark(r,c))d+='M'+(c+m)+','+(r+m)+'h1v1h-1z';var w=(n+2*m);return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+w+' '+w+'" width="'+w*s+'" height="'+w*s+'" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="#fff"/><path fill="'+UI.$('#fg').value+'" d="'+d+'"/></svg>'}
UI.$('#svg').onclick=function(){if(q)UI.download(new Blob([svg(10)],{type:'image/svg+xml'}),'qr-code.svg')};
UI.$('#png').onclick=function(){if(!q)return;var n=q.getModuleCount()+8,s=Math.max(4,Math.ceil(1000/n)),c=document.createElement('canvas');c.width=c.height=n*s;var x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.fillStyle=UI.$('#fg').value;
for(var r=0;r<n-8;r++)for(var k=0;k<n-8;k++)if(q.isDark(r,k))x.fillRect((k+4)*s,(r+4)*s,s,s);c.toBlob(function(b){UI.download(b,'qr-code.png')})};"""+LIVE
add("qr-code-generator","Productivity","QR Code Generator","Free QR Code Generator – URL, Wi-Fi, Email, No Sign-Up, No Expiry","Create QR codes for websites, Wi-Fi, email and phone numbers. Download PNG or SVG. Static codes that never expire, no tracking, no sign-up.",ui,js,
"<h2>Static QR codes that never expire</h2><p>Many “free” QR sites create <i>dynamic</i> codes that redirect through their servers and stop working when a trial ends. Codes made here are <b>static</b>: the URL or text is encoded directly in the pattern, so they work forever and nobody tracks the scans.</p><h2>Wi-Fi QR codes</h2><p>Choose <i>Wi-Fi network</i>, enter the network name and password, and print the code for your office reception or meeting room. iPhone and Android cameras join the network when they scan it.</p><h2>Printing tips</h2><ul><li>Print at least 2 × 2 cm (0.8 in); larger for scanning from a distance (about 1/10 of the scan distance).</li><li>Use dark on light with high contrast. Don't invert colors.</li><li>Use SVG for print—it scales without blur.</li><li>Choose High error correction if a logo will cover part of the code.</li></ul>"+FAQ(("Are QR codes free for commercial use?","Yes. QR Code is a registered trademark of Denso Wave, which allows free use of the standard."),("Is my data stored?","No. The code is generated in your browser.")),libs=("qrcode.js",))
# password generator
ui="<div class='calc wide'><label for='len'>Length: <output id='lv'>16</output> characters</label><input id='len' type='range' min='6' max='64' value='16'><div class='opts'><label class='chk'><input id='up' type='checkbox' checked> Uppercase (A-Z)</label><label class='chk'><input id='lo' type='checkbox' checked> Lowercase (a-z)</label><label class='chk'><input id='di' type='checkbox' checked> Numbers (0-9)</label><label class='chk'><input id='sy' type='checkbox' checked> Symbols (!@#$…)</label><label class='chk'><input id='ns' type='checkbox'> Avoid look-alike characters (I, l, 1, O, 0, o)</label><label for='cnt'>How many</label><select id='cnt'><option>1</option><option>5</option><option>10</option></select></div><button type='button' class='btn' id='go'>Generate password</button><label for='pw'>Password</label><textarea id='pw' rows='3' readonly spellcheck='false' style='font-family:ui-monospace,Consolas,monospace;font-size:18px'></textarea><p id='st' class='muted'></p><button type='button' class='btn ghost' id='cp'>Copy</button></div><p class='priv'>🔒 Passwords are generated on your device with your browser's cryptographic random generator. They are never sent or stored anywhere.</p>"
js="""function gen(){try{var o={length:+UI.$('#len').value,upper:UI.$('#up').checked,lower:UI.$('#lo').checked,digits:UI.$('#di').checked,symbols:UI.$('#sy').checked,noSimilar:UI.$('#ns').checked},n=+UI.$('#cnt').value,L=[],r;for(var i=0;i<n;i++){r=DK.password(o);L.push(r.password)}UI.$('#pw').value=L.join('\\n');UI.$('#pw').rows=Math.min(10,Math.max(3,n));UI.$('#st').textContent='Strength: '+DK.pwStrength(r.bits)+' (~'+r.bits+' bits of entropy)'}catch(e){UI.$('#pw').value='';UI.$('#st').textContent=e.message}}
UI.$('#len').oninput=function(){UI.$('#lv').textContent=this.value;gen()};['#up','#lo','#di','#sy','#ns','#cnt'].forEach(function(s){UI.$(s).addEventListener('change',gen)});UI.$('#go').onclick=gen;UI.$('#cp').onclick=function(){UI.copy(UI.$('#pw').value,this)};gen();"""
add("password-generator","Productivity","Password Generator","Strong Password Generator – Random, Secure, Free","Generate strong random passwords in your browser: choose length, uppercase, lowercase, numbers and symbols, avoid look-alike characters, create up to 10 at once.",ui,js,
"<h2>What makes a password strong?</h2><p>Length matters most. Each extra character multiplies the number of possible passwords, so a random 16-character password using upper and lower case letters, numbers and symbols is far harder to guess than a clever 8-character one. The strength meter shows the entropy in bits: roughly, every additional bit doubles the work needed to guess it.</p><ul><li><b>Under 40 bits:</b> weak—avoid for anything important.</li><li><b>60–80 bits:</b> strong for most online accounts.</li><li><b>80+ bits:</b> very strong; use for email, banking and password-manager master passwords.</li></ul><h2>Truly random, generated locally</h2><p>Passwords are created with <code>crypto.getRandomValues</code>, the cryptographically secure random number generator built into your browser, using unbiased selection. At least one character from every type you tick is included. Nothing is sent over the network or saved.</p><h2>Good password habits</h2><ul><li>Use a different password for every account; a password manager makes this easy.</li><li>Turn on two-factor authentication where available.</li><li>Tick <i>Avoid look-alike characters</i> if you will need to read or type the password by hand.</li></ul>"+FAQ(("Is it safe to use an online password generator?","This one runs entirely in your browser and never transmits the password. You can even disconnect from the internet after the page loads and it keeps working."),("How long should my password be?","At least 12 characters; 16 or more is better. Some sites cap the length or restrict symbols—untick Symbols if a site rejects them."),("Do you store generated passwords?","No. There is no server-side code and no storage; closing the tab erases them.")))
# email signature
F=[("name","Full name","Jordan Smith"),("title","Job title","Marketing Manager"),("company","Company","Acme Inc."),("phone","Phone","(555) 123-4567"),("email","Email","jordan@acme.com"),("website","Website","acme.com"),("address","Address (optional)",""),("photo","Photo/logo image URL (optional, https://…)","")]
ui="<form class='calc' onsubmit='return false'>"+"".join(f"<label for='{i}'>{l}</label><input id='{i}' type='text' value='{v}'>" for i,l,v in F)+"<label for='color'>Accent color</label><input id='color' type='color' value='#1d4ed8'></form><div class='res light'><h2>Preview</h2><div id='pv' class='sigpv'></div><div class='btnrow'><button type='button' class='btn sm' id='cr'>Copy signature</button><button type='button' class='btn sm ghost' id='ch'>Copy HTML code</button></div><p class='muted'>Use “Copy signature”, then paste into Gmail or Outlook signature settings.</p></div>"
js="""function val(){var o={};"""+"".join(f"o.{i}=UI.$('#{i}').value.trim();" for i,_,_ in F)+"""o.color=UI.$('#color').value;return o}function run(){UI.$('#pv').innerHTML=DK.signature(val())}
UI.$('#ch').onclick=function(){UI.copy(DK.signature(val()),this)};UI.$('#cr').onclick=function(){var h=DK.signature(val()),b=this;if(window.ClipboardItem&&navigator.clipboard&&navigator.clipboard.write){navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([h],{type:'text/html'}),'text/plain':new Blob([UI.$('#pv').innerText],{type:'text/plain'})})]).then(function(){b.textContent='Copied!';setTimeout(function(){b.textContent='Copy signature'},1500)})}else{var r=document.createRange();r.selectNode(UI.$('#pv'));getSelection().removeAllRanges();getSelection().addRange(r);document.execCommand('copy');getSelection().removeAllRanges();b.textContent='Copied!'}};"""+LIVE
add("email-signature-generator","Productivity","Email Signature Generator","Free Email Signature Generator for Gmail & Outlook – No Sign-Up","Create a clean, professional email signature for Gmail, Outlook and Apple Mail. Live preview, one-click copy, no sign-up and no branding.",ui,js,
"<h2>How to add the signature</h2><h3>Gmail</h3><ol><li>Click <b>Copy signature</b>.</li><li>In Gmail open Settings (gear) → See all settings → General → Signature → Create new.</li><li>Paste with Ctrl+V / Cmd+V and click Save Changes at the bottom.</li></ol><h3>Outlook (new Outlook and web)</h3><ol><li>Settings → Accounts → Signatures → New signature.</li><li>Paste and save, then choose it as the default for new messages and replies.</li></ol><h3>Apple Mail</h3><p>Mail → Settings → Signatures → +, paste, then untick “Always match my default message font”.</p><h2>Why a table-based layout?</h2><p>Email clients ignore most modern CSS. The signature uses simple tables and inline styles—the approach that renders consistently in Gmail, Outlook and phones.</p><h2>Adding a photo or logo</h2><p>Email signatures can't embed files reliably; link to an image hosted online (for example your company website or LinkedIn photo URL).</p>"+FAQ(("Is there a watermark or branding?","No."),("Is my information stored?","No. Everything happens in your browser.")))
# csv json
ui="<div class='calc wide two'><div><label for='i'>Input</label><textarea id='i' rows='12'>name,email,age\nAna,ana@example.com,31\n\"Lee, Sam\",sam@example.com,28</textarea></div><div><label for='o'>Output</label><textarea id='o' rows='12' readonly></textarea></div></div><div class='btnrow'><select id='dir'><option value='c2j'>CSV → JSON</option><option value='j2c'>JSON → CSV</option></select><label class='chk'><input id='ty' type='checkbox' checked> Convert numbers &amp; booleans</label><button type='button' class='btn sm' id='cp'>Copy</button><button type='button' class='btn sm ghost' id='dl'>Download</button></div><p id='status' class='status'></p><p class='priv'>🔒 Your data stays in your browser.</p>"
js="""function run(){try{var i=UI.$('#i').value;UI.$('#o').value=UI.$('#dir').value==='c2j'?JSON.stringify(DK.csvToJson(i,{types:UI.$('#ty').checked}),null,2):DK.jsonToCsv(i);UI.status('')}catch(e){UI.$('#o').value='';UI.status('Invalid input: '+e.message,1)}}
UI.$('#cp').onclick=function(){UI.copy(UI.$('#o').value,this)};UI.$('#dl').onclick=function(){var j=UI.$('#dir').value==='c2j';UI.download(new Blob([UI.$('#o').value],{type:j?'application/json':'text/csv'}),j?'data.json':'data.csv')};
['#i','#dir','#ty'].forEach(function(s){UI.$(s).addEventListener('input',run);UI.$(s).addEventListener('change',run)});run();"""
add("csv-to-json","Spreadsheet tools","CSV to JSON Converter","CSV to JSON and JSON to CSV Converter – Free, Private","Convert CSV to JSON (array of objects) or JSON to CSV. Handles quoted fields, commas and line breaks inside cells, and semicolon or tab delimiters.",ui,js,
"<h2>How the conversion works</h2><p>The first CSV row is used as the keys, and each following row becomes one JSON object. Quoted fields are parsed per RFC 4180, so values like <code>\"Lee, Sam\"</code>, doubled quotes and line breaks inside a cell are handled correctly. Comma, semicolon, tab and pipe delimiters are detected automatically.</p><h2>Numbers and booleans</h2><p>With the option on, <code>31</code> becomes the number 31 and <code>true</code> a boolean; empty cells become null. Values with leading zeros like <code>00123</code> stay strings so ZIP codes and IDs aren't damaged.</p><h2>JSON to CSV</h2><p>Paste an array of objects. The header is the union of all keys, so objects with missing fields still line up. Nested objects are written as JSON text in the cell.</p>"+FAQ(("Is there a size limit?","It handles several MB comfortably; for very large files use the CSV to Excel tool with file upload."),))
